SELECT  FROM skill_flow
WHERE deleted_at IS NULL AND created_by = #{ownerUserId}
AND enabled = #{enabled}

    AND (LOWER(name) LIKE CONCAT('%', LOWER(#{keyword}), '%')
         OR LOWER(code) LIKE CONCAT('%', LOWER(#{keyword}), '%'))

AND created_by = #{createdBy}
ORDER BY updated_at DESC, id DESC

SELECT  FROM skill_metric_readiness
WHERE data_date=#{dataDate} AND status='READY' AND metric_id IN
#{metricId}
